deps = {  # 서비스·패키지 → 기대는 사내 패키지 (가상)
    "deposit": ["ui", "http"], "card": ["ui", "http"], "loan": ["ui", "http", "funnel"],
    "admin": ["ui"], "ui": [], "http": ["auth"], "auth": [], "funnel": [],
}
services = {"deposit", "card", "loan", "admin"}
ENVS, BUILD_MIN, TRIGGER_MIN = 3, 5, 1   # 개발·스테이징·라이브, 빌드 5분, 트리거 1분

def affected(changed):
    out, todo = {changed}, [changed]
    while todo:
        p = todo.pop()
        for name, ds in deps.items():
            if p in ds and name not in out:
                out.add(name); todo.append(name)
    return sorted(out & services)

for changed in ("auth", "funnel", "admin"):
    s = affected(changed)
    builds = len(s) * ENVS
    print(f"{changed:>6} 변경 → 다시 빌드할 서비스 {s} · 빌드 {builds}번 · "
          f"차례로 {builds * BUILD_MIN}분 · 따로 띄워 동시에 {TRIGGER_MIN + BUILD_MIN if builds else 0}분")

sections = {  # 화면 영역 → 부르는 API (가상의 계좌 상세 화면)
    "잔액": ["/balance"], "거래 내역": ["/transactions"],
    "추천 상품": ["/recommend"], "이자 받기 버튼": ["/balance", "/interest"],
}

def render(force_500, isolated):
    shown = []
    for name, apis in sections.items():
        broken = any(a in force_500 for a in apis)
        if broken and not isolated:
            return "화면 전체 오류"                # 한 곳의 실패가 페이지를 통째로 멈춤
        shown.append(f"{name}:{'대체 화면' if broken else '정상'}")
    return " · ".join(shown)

for target in ("/recommend", "/balance"):
    print(f"[{target} 를 500으로]")
    print("  영역을 안 나눴을 때 →", render({target}, isolated=False))
    print("  영역마다 막았을 때 →", render({target}, isolated=True))

import http.server, threading, urllib.request, urllib.error

class Fake(http.server.BaseHTTPRequestHandler):   # 가상 API 서버: /v2/accounts 만 있다
    def do_GET(self):
        self.send_response(200 if self.path == "/v2/accounts" else 404); self.end_headers()
    def log_message(self, *a): pass

srv = http.server.HTTPServer(("127.0.0.1", 0), Fake)
threading.Thread(target=srv.serve_forever, daemon=True).start()
base = f"http://127.0.0.1:{srv.server_port}"

before = {"ACCOUNTS_API": "/v1/accounts"}
after = {"ACCOUNTS_API": "/v2/accounts", "CARDS_API": "/v2/card"}   # PR 이 바꾼 설정(오타 하나)

def check(after, before):
    failed = []
    for key, path in after.items():
        if before.get(key) == path:
            continue                              # 안 바뀐 줄은 묻지 않는다
        try:
            code = urllib.request.urlopen(base + path, timeout=3).status
        except urllib.error.HTTPError as e:
            code = e.code
        print(f"{key:<13} {path:<14} → {code}")
        if not 200 <= code < 300:
            failed.append(key)
    return failed

failed = check(after, before)
print("CI 결과:", "실패 — 머지 막음 " + str(failed) if failed else "통과")
srv.shutdown()
